```

The Saving… label never appears in this form. Why?

```jsx
'use client'
import { useFormStatus } from 'react-dom'

export default function NewPost({ createPost }) {
  const { pending } = useFormStatus()
  return (
    <form action={createPost}>
      <input name="title" />
      <button disabled={pending}>{pending ? 'Saving…' : 'Save'}</button>
    </form>
  )
}
```

Submitting this form throws `TypeError: formData.get is not a function`. Why?

```jsx
// actions.js
'use server'
export async function subscribe(formData) {
  const email = formData.get('email')
  // ...
  return { ok: true }
}

// signup.jsx
'use client'
import { useActionState } from 'react'
import { subscribe } from './actions'

export function Signup() {
  const [state, formAction] = useActionState(subscribe, null)
  return <form action={formAction}><input name="email" /></form>
}
